namespace Kaff.Api.Features.DailyLogs.CorrectQuantity;

/// <summary>
/// The figure the saved quantity should read, not the difference: the server stores the difference as a signed delta.
/// </summary>
/// <param name="CorrectionId">Generated by the device, so a retried request is recognised and not applied twice.</param>
/// <param name="Quantity">The corrected quantity. Positive.</param>
public sealed record Request(Guid? CorrectionId, decimal Quantity);
